INSERT INTO faqs (question, answer, sort_order) VALUES
  ('Do you accept walk-ins?', 'Yes, when a stylist is free. Booking ahead guarantees your time, especially at weekends.', 0),
  ('Do you do home service?', 'Yes, for many services. A transport fee applies depending on your location.', 1),
  ('How do I book bridal makeup?', 'Use the Bridal & Group Bookings page or WhatsApp us with your date. We recommend a trial before the day.', 2),
  ('Do I need to pay a deposit?', 'Deposits are needed for bridal, group and home-service bookings to secure your slot.', 3),
  ('Do you sell hair and products?', 'Ask us. We can advise and source quality hair and products for you.', 4);
